css:
body { margin: 0; }
.big { all: unset; box-sizing: border-box; cursor: pointer; width: 100%; height: 100vh; min-height: 48px; display: grid; align-content: center; justify-items: start; gap: 4px;
  padding: var(--tile-pad, 14px); border-radius: var(--tile-radius, 20px); font-family: var(--font-family); color: var(--tile-fg); }
.big:focus-visible { outline: var(--focus-width, 3px) solid var(--focus-color, currentColor); outline-offset: -6px; }
.big[aria-pressed="true"] { background: var(--tile-on-bg); color: var(--tile-on-fg); }
.dot { width: 40px; height: 40px; border-radius: 50%; background: var(--tile-icon-bg); }
.big[aria-pressed="true"] .dot { background: var(--tile-icon-on-bg); }
.label { font-size: 22px; line-height: 28px; font-weight: var(--weight-strong, 600); }
.state { font-size: var(--type-body-s-size, 13px); opacity: .8; }

js:
function onHomeyReady(Homey) {
  const settings = Homey.getSettings();
  const button = document.querySelector('.big');
  function show() {
    const device = Homey.devices.get(settings.device);
    const on = !!(device && device.capabilities.onoff && device.capabilities.onoff.value === true);
    button.setAttribute('aria-pressed', on ? 'true' : 'false');
    document.querySelector('.label').textContent = settings.label || (device ? device.name : Homey.__('choose'));
    document.querySelector('.state').textContent = device ? Homey.__(on ? 'on' : 'off') : '';
    button.disabled = !(device && device.capabilities.onoff && device.capabilities.onoff.setable);
  }
  button.addEventListener('click', () => {
    const device = Homey.devices.get(settings.device);
    if (!device || !device.capabilities.onoff) return;
    Homey.devices.setCapabilityValue(device.id, 'onoff', device.capabilities.onoff.value !== true);
  });
  Homey.on('device', show);
  show();
  Homey.ready();
}
